import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define WARP_SIZE 32
#define ROWS_PER_BLOCK 4
#define TILE_K4 512
#define BLOCK_THREADS 256
__global__ void matvec_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int K) {
    int block_row0 = blockIdx.x * ROWS_PER_BLOCK;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int K4 = K / 4;
    const float4* B_vec = reinterpret_cast<const float4*>(B);
    __shared__ float4 sB[2][TILE_K4];
    float sum[ROWS_PER_BLOCK];
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; ++r) sum[r] = 0.0f;
    const float4* A_row_ptr[ROWS_PER_BLOCK];
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
        int row = block_row0 + r;
        if (row < M) {
            A_row_ptr[r] = reinterpret_cast<const float4*>(A + (size_t)row * K);
        } else {
            A_row_ptr[r] = nullptr;
        }
    }
    int num_tiles = (K4 + TILE_K4 - 1) / TILE_K4;
    if (num_tiles > 0) {
        int first_len = min(TILE_K4, K4);
        for (int i = tid; i < first_len; i += nthreads) {
            sB[0][i] = B_vec[i];
        }
        __syncthreads();
        int buf = 0;
        for (int t = 0; t < num_tiles; ++t) {
            int cur_tile_start = t * TILE_K4;
            int cur_tile_len = min(TILE_K4, K4 - cur_tile_start);
            int next_buf = buf ^ 1;
            int next_tile_start = cur_tile_start + TILE_K4;
            int next_tile_len = (next_tile_start < K4) ? min(TILE_K4, K4 - next_tile_start) : 0;
            if (next_tile_len > 0) {
                for (int i = tid; i < next_tile_len; i += nthreads) {
                    sB[next_buf][i] = B_vec[next_tile_start + i];
                }
            }
            #pragma unroll
            for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
                if (A_row_ptr[r] == nullptr) continue;
                const float4* A_row = A_row_ptr[r];
                for (int i = tid; i < cur_tile_len; i += nthreads) {
                    float4 a = A_row[cur_tile_start + i];
                    float4 b = sB[buf][i];
                    sum[r] += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
                }
            }
            __syncthreads();
            buf = next_buf;
        }
    }
    // remainder (K not divisible by 4)
    int rem_start = K4 * 4;
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
        int row = block_row0 + r;
        if (row >= M) continue;
        for (int i = rem_start + tid; i < K; i += nthreads) {
            sum[r] += A[(size_t)row * K + i] * B[i];
        }
    }
    // warp-level reduction per row
    unsigned mask = 0xffffffff;
    int lane = tid % WARP_SIZE;
    int warp_id = tid / WARP_SIZE;
    int num_warps = (nthreads + WARP_SIZE - 1) / WARP_SIZE;
    __shared__ float warp_sums[ROWS_PER_BLOCK][32];
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
        float v = sum[r];
        for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
            v += __shfl_down_sync(mask, v, offset);
        }
        if (lane == 0) {
            warp_sums[r][warp_id] = v;
        }
    }
    __syncthreads();
    if (warp_id == 0) {
        #pragma unroll
        for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
            float val = (lane < num_warps) ? warp_sums[r][lane] : 0.0f;
            for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
                val += __shfl_down_sync(mask, val, offset);
            }
            if (lane == 0) {
                int row = block_row0 + r;
                if (row < M) {
                    C[row] = val;
                }
            }
        }
    }
}
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    auto C = torch::empty({M, 1}, A.options());
    const int threads = BLOCK_THREADS;
    const int blocks = (M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    matvec_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );
    return C;
}
"""

cpp_source = r"""
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);
"""

matvec_module = load_inline(
    name="matvec_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matvec_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matvec = matvec_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().float()
        B = B.cuda().float()
        return self.matvec.matvec_cuda(A, B)


M = 256 * 8  # 2048
K = 131072 * 8  # 1048576


def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, 1)
    return [A, B]


def get_init_inputs():
    return []

